import type { AuthContext, Env } from '../types.js';

const DEFAULT_ACCOUNT_ID = 'self-hosted';

interface ApiKeyRecord {
  account_id: string;
  is_admin: number;
}

function isHostedMode(env: Env): boolean {
  return env.NIMBUS_HOSTED === 'true';
}

export function createSelfHostedAuthContext(): AuthContext {
  return {
    accountId: DEFAULT_ACCOUNT_ID,
    isAdmin: true,
    isAuthenticated: false,
    isHostedMode: false,
  };

import type { AuthContext } from '../types.js';

export function canAccessAccount(authContext: AuthContext, accountId: string | null | undefined): boolean {
  if (!authContext.isHostedMode) {
    return true;
  }
  if (authContext.isAdmin) {
    return true;
  }
  if (!authContext.isAuthenticated) {
    return false;
  }
  return typeof accountId === 'string' && accountId === authContext.accountId;
}

