              const start = match[2];
              const end = match[3];
              const anchor = end ? `#L${start}-L${end}` : `#L${start}`;
              const encodedPath = filePath
                .split('/')
                .map(segment => encodeURIComponent(segment))
                .join('/');
              const url = `${context.serverUrl}/${owner}/${repo}/blob/${headSha}/${encodedPath}${anchor}`;
              return `[${filePath}${anchor}](${url})`;
            }

            function locationToRaw(location) {
              if (!location || typeof location !== 'object') {
                return '';
              }

              const path =
                (typeof location.filePath === 'string' && location.filePath) ||
                (typeof location.path === 'string' && location.path) ||
                '';
              const start =
                Number.isInteger(location.startLine) ? String(location.startLine) :
                Number.isInteger(location.line) ? String(location.line) :
                '';
              const end = Number.isInteger(location.endLine) ? String(location.endLine) : '';

              if (!path) {
                return '';
              }

              if (!start) {
                return path;
              }

              return end ? `${path}:${start}-${end}` : `${path}:${start}`;
            }

            function buildCardsFromStructuredReview(review) {
              if (!review || typeof review !== 'object' || !Array.isArray(review.findings) || review.findings.length === 0) {
                return null;
              }

              const cards = review.findings.map((finding, index) => {
                const severity = typeof finding?.severity === 'string' ? finding.severity : 'unknown';
                const type = typeof finding?.category === 'string' ? finding.category : 'unknown';
                const scope = typeof finding?.passType === 'string' ? finding.passType : 'single';
                const summary =
                  (typeof finding?.description === 'string' && finding.description.trim()) ||
                  (typeof finding?.title === 'string' && finding.title.trim()) ||
                  'No summary provided.';

                const firstLocation = Array.isArray(finding?.locations) ? finding.locations[0] : null;
                const locationRaw = locationToRaw(firstLocation);

                return [
                  `### F-${String(index + 1).padStart(3, '0')}`,
                  `- Severity: ${severity}`,
                  `- Type: ${type}`,
                  `- Scope: ${scope}`,
                  `- Summary: ${summary}`,
                  `- Why this matters: ${buildWhyMatters(severity, type)}`,
                  `- Location: ${buildLocationMarkdown(locationRaw)}`,
                ].join('\n');
              });

              return cards.join('\n\n');
            }

            let findingsBody = 'No findings report was produced for this run.';

            if (reviewId && fs.existsSync(reviewPath)) {
              const exported = JSON.parse(fs.readFileSync(reviewPath, 'utf8'));
              const review = exported && typeof exported === 'object' && exported.review ? exported.review : exported;

              const structuredCards = buildCardsFromStructuredReview(review);
              if (structuredCards) {
                findingsBody = structuredCards;
              } else if (review && Array.isArray(review.findings) && review.findings.length === 0) {
                findingsBody = 'No actionable findings.';
              }
            }

            let body = `${marker}\n## Nimbus Findings\n\n- Review ID: \`${reviewId || 'unknown'}\`\n- Head SHA: \`${headSha}\`\n- Schema version: \`v1\`\n\n${findingsBody}`;

            if (body.length > 65536) {
              body = `${body.slice(0, 65520)}\n\n... (truncated)`;
            }

            const created = await github.rest.issues.createComment({
              owner,
              repo,
              issue_number,
              body,
            });
            core.info(`Created Nimbus findings comment: ${created.data.id} for ${headSha}`);

      - name: Finalize as informational check
        if: always()
        run: |
          echo "Nimbus PR review completed (informational mode)."
          exit 0

import * as p from '@clack/prompts';
import { appendFile } from 'fs/promises';
import { exchangeOidcToken, getWorkerUrl } from '../../lib/api.js';

interface GithubOidcResponse {
  value?: string;
}

async function requestGithubOidcToken(audience: string): Promise<string> {
  const requestUrlRaw = process.env.ACTIONS_ID_TOKEN_REQUEST_URL;
  const requestToken = process.env.ACTIONS_ID_TOKEN_REQUEST_TOKEN;
  if (!requestUrlRaw || !requestToken) {
    throw new Error('this command requires a GitHub Actions environment');
  }

  const requestUrl = new URL(requestUrlRaw);
  requestUrl.searchParams.set('audience', audience);

  const response = await fetch(requestUrl.toString(), {
    headers: {
      Authorization: `Bearer ${requestToken}`,
    },
  });
  if (!response.ok) {
    const details = await response.text();
    throw new Error(`Failed to request GitHub OIDC token (${response.status}): ${details}`);
  }

  const payload = (await response.json()) as GithubOidcResponse;
  const token = typeof payload.value === 'string' ? payload.value.trim() : '';
  if (!token) {
    throw new Error('GitHub OIDC response did not include a token value');
  }
  return token;
}

export async function authExchangeCommand(): Promise<void> {
  const githubOutputPath = typeof process.env.GITHUB_OUTPUT === 'string' ? process.env.GITHUB_OUTPUT.trim() : '';
  if (!githubOutputPath) {
    throw new Error('GITHUB_OUTPUT is required for nimbus auth exchange output in GitHub Actions');
  }

  const workerUrl = getWorkerUrl();
  const oidcToken = await requestGithubOidcToken('nimbus');
  const exchanged = await exchangeOidcToken(workerUrl, oidcToken);

  await appendFile(githubOutputPath, `token=${exchanged.token}\n`, 'utf8');
  p.log.success('Exchanged GitHub OIDC token for Nimbus token.');
}

import * as p from '@clack/prompts';
import { execFileSync } from 'child_process';
import { getWorkerUrl, registerRepo } from '../../lib/api.js';

function parseRepoSlug(remoteUrl: string): string | null {
  const trimmed = remoteUrl.trim();
  if (!trimmed) {
    return null;
  }

  if (trimmed.startsWith('git@')) {
    const idx = trimmed.indexOf(':');
    if (idx < 0) {
      return null;
    }
    const path = trimmed.slice(idx + 1).replace(/\.git$/i, '');
    return /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(path) ? path : null;
  }

  try {
    const parsed = new URL(trimmed);
    const path = parsed.pathname.replace(/^\//, '').replace(/\.git$/i, '');
    return /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(path) ? path : null;
  } catch {
    return null;
  }
}

function detectRepoSlugFromGitOrigin(): string {
  let origin = '';
  try {
    origin = execFileSync('git', ['remote', 'get-url', 'origin'], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    }).trim();
  } catch (error) {
    const details = error instanceof Error ? error.message : String(error);
    throw new Error(`Could not detect git remote origin: ${details}`);
  }

  const slug = parseRepoSlug(origin);
  if (!slug) {
    throw new Error('Could not infer repo slug from git remote origin. Provide --repo <owner/repo>.');
  }
  return slug;
}

export async function registerRepoCommand(options?: { repo?: string }): Promise<void> {
  const workerUrl = getWorkerUrl();
  const repoSlug = typeof options?.repo === 'string' && options.repo.trim() ? options.repo.trim() : detectRepoSlugFromGitOrigin();

  try {
    const response = await registerRepo(workerUrl, repoSlug);
    if (response.status === 'already_registered') {
      p.log.success(`Repository already registered: ${response.repoSlug}`);
      p.log.message(`Account ID: ${response.accountId}`);
      return;
    }

    p.log.success(`Repository registered: ${response.repoSlug}`);
    p.log.message(`Account ID: ${response.accountId}`);
    p.log.message('Setup complete. CI can now exchange GitHub OIDC tokens for short-lived Nimbus auth tokens.');
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (message.includes('Worker error (409)')) {
      throw new Error(
        `Repository ${repoSlug} is already registered to a different Nimbus account. Ask an admin to transfer ownership.`
      );
    }
    throw error;
  }
}

