              const latestPr = latest.data;
              const latestHead = latestPr?.head?.sha;
              const latestBase = latestPr?.base?.sha;
              const authorLogin = latestPr?.user?.login;

              let hasWriteLikeAccess = false;
              if (authorLogin) {
                try {
                  const permission = await github.rest.repos.getCollaboratorPermissionLevel({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    username: authorLogin,
                  });
                  const level = permission.data.permission;
                  hasWriteLikeAccess = level === 'admin' || level === 'maintain' || level === 'write';
                } catch (error) {
                  core.warning(`Runtime permission check failed for ${authorLogin}; treating PR as untrusted.`);
                }
              }

              trustedRuntime =
                latestPr?.head?.repo?.fork === false &&
                latestPr?.head?.repo?.full_name === repoFullName &&
                latestPr?.head?.repo?.owner?.login === context.repo.owner &&
                hasWriteLikeAccess &&
                latestHead === expectedHead &&
                latestBase === expectedBase;

              reason = trustedRuntime
                ? 'ok'
                : latestHead !== expectedHead
                  ? `stale_head:${expectedHead}->${latestHead}`
                  : latestBase !== expectedBase
                    ? `stale_base:${expectedBase}->${latestBase}`
                  : 'runtime_trust_check_failed';
            } catch (error) {
              reason = `runtime_check_error:${error.message}`;
              core.warning(`Runtime trust revalidation failed: ${error.message}`);
            }

            core.setOutput('trusted_runtime', trustedRuntime ? 'true' : 'false');
            core.setOutput('reason', reason);

            if (!trustedRuntime) {
              core.warning(`Skipping review creation because runtime trust check failed (${reason}).`);
            }

      - name: Run Nimbus review create
        id: auth_exchange
        if: steps.pr_context.outputs.trusted_pr == 'true' && steps.runtime_guard.outputs.trusted_runtime == 'true'
        run: |
          node packages/cli/dist/index.js auth exchange

      - name: Run Nimbus review create
